import{_ as t,c as o,o as a,ah as n}from"./chunks/framework.PvdZnrZd.js";const g=JSON.parse('{"title":"Subscription Pause","description":"Subscription Pause","frontmatter":{"title":"Subscription Pause","description":"Subscription Pause","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/subscription-plan/subscription-plan.md","filePath":"zenith/subscription-plan/subscription-plan.md"}'),s={name:"zenith/subscription-plan/subscription-plan.md"};function r(p,e,i,l,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<p>Do you ever feel the need to pause the subscription of an application for the time being?<br> Well, <a href="/zenith/introduction/">Multivendor Marketplace App</a> for Shopify is now up with the same feature.</p><p>You can now easily pause your marketplace app&#39;s subscription for as long as you are away.</p><p>Let&#39;s see how to do the same and all the FAQs related to it!</p><h2 id="pricing" tabindex="-1"><strong>Pricing</strong> <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;**Pricing**&quot;">​</a></h2><p>While your application is paused, you need to pay <strong>25%</strong> of your ongoing monthly multivendor app charge. Moreover, the charges can&#39;t get <strong>less than $10</strong> and <strong>higher than $25</strong> and need to be paid monthly.</p><p>Explaining the pricing scenario using two examples:</p><p><strong>Example I</strong></p><p>Suppose you are billed $120 per month for using the app then you&#39;ll need to pay 25% of $120.</p><p>That will be $30. But because the maximum charges are $25 which means you need to pay $25 instead of $30 as the monthly subscription pause charge.</p><p><strong>Example II</strong></p><p>Suppose you are billed $30 per month for using the app then you&#39;ll need to pay 25% of $30.</p><p>That will be $7.5. But, similarly, the minimum charges are $10 which means you need to pay $10 instead of $7.5 as the monthly subscription pause charge.</p><h2 id="the-process" tabindex="-1">The Process <a class="header-anchor" href="#the-process" aria-label="Permalink to &quot;The Process&quot;">​</a></h2><p>To pause the app, visit: <strong>Multivendor Marketplace Admin Panel</strong> &gt; <strong>Hover over the three dots</strong> on the top right of dashboard &gt; Click on <strong>Upgrade Plan</strong> option from the drop-down. Refer:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/appplan.webp" alt="Multivendor Marketplace Admin Panel &gt; Upgrade Plan"></p><p>Further, on the redirected page, click on the <strong>Pause Subscription</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/pausesubscription.webp" alt="pause plan"></p><p>You will receive a pop-up like so:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/pausesubscriptionn.webp" alt="pause subscription"></p><p>This action will redirect you to the Shopify Approve App Charges page. There you need to approve the charges and proceed. Further, you&#39;ll land on a page like this:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/resumesubscription.webp" alt="Choose-Plan-3"></p><p>Here, you&#39;ll have the <strong>Resume Subscription</strong> button which you can use whenever you&#39;ll wish to get back.</p><p><strong>Note:</strong> Whenever you&#39;ll open the app from the &#39;App section&#39; of Shopify backend, you&#39;ll land on the page shown above.</p><p>You won&#39;t be able to access the Multivendor backend until and unless you resume the app&#39;s subscription.</p><p>Similarly, whenever your sellers will log in to their seller panel, they&#39;ll land on the page like so:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/03/Contant-Admin-%E2%80%A2-Multivendor-MarketPlace-1-1200x597.png" alt="Contant-Admin-•-Multivendor-MarketPlace-1"></p><p>This is the process to pause your Marketplace App&#39;s subscription. Now, let&#39;s see some of the queries that might be popping in your head!</p><h2 id="related-faqs" tabindex="-1">Related FAQs <a class="header-anchor" href="#related-faqs" aria-label="Permalink to &quot;Related FAQs&quot;">​</a></h2><p><strong>Question:</strong> In case the customer is using multivendor marketplace feature apps, will he need to pay for them while the app is paused?</p><p><strong>Answer:</strong> The customer needs to pay <strong>25%</strong> of the total monthly marketplace charges. The user will be charged monthly. Also, the charges can&#39;t get <strong>less than $10</strong> and <strong>higher than $25.</strong></p><p><strong>Question:</strong> Will my data remain saved while the app is paused?</p><p><strong>Answer:</strong> Yes, the data will be saved at our end while your app&#39;s subscription is paused.</p><p><strong>Question:</strong> Does the customer need to pay outstanding charges before pausing the marketplace subscription?</p><p><strong>Answer:</strong> No, you will receive the bill at the end of the month.</p><p><strong>Question:</strong> Can the customer pause the marketplace app while being on the free trial period?</p><p><strong>Answer:</strong> No, the app can&#39;t be paused if you are on a free trial period or even if you are using it on the partner-friendly store.</p><p><strong>Question:</strong> Will I be able to access the app&#39;s backend while it&#39;s in pause state?</p><p><strong>Answer:</strong> No, neither the admin nor the seller can access the backend of the multivendor marketplace app. Which means:</p><ul><li>Admin can&#39;t make changes to the configurations, products, sellers or any other marketplace data.</li><li>No webhook will work.</li><li>Sellers won&#39;t be able to login to their seller panels.</li><li>Product updates done at Shopify end will not sync with the Multivendor Marketplace app.</li></ul><p><strong>Question:</strong> Will the seller profile be visible on my storefront?</p><p><strong>Answer:</strong> No, the seller listing page or the seller profile page will not be displayed on the frontend if the app is paused.</p><p><strong>Question:</strong> When can I resume my subscription?</p><p><strong>Answer:</strong> You can resume the subscription anytime you want by clicking on the app from the Shopify app section.</p><h2 id="need-help" tabindex="-1">Need Help? <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need Help?&quot;">​</a></h2><p>Furthermore, if you have any issues, please drop an email at <a href="mailto:support@webkul.com" target="_blank" rel="noreferrer">support@webkul.com</a>. You can also create a ticket at  <a href="https://webkul.uvdesk.com/" target="_blank" rel="noreferrer">Webkul UV Desk</a>.</p>',45)])])}const d=t(s,[["render",r]]);export{g as __pageData,d as default};
